import type { JSX } from "@solidjs/web";
import { omit } from "solid-js";

import "./aspect-ratio.css";

/**
 * AspectRatio, shadcn's AspectRatio: shows its content at a fixed width to
 * height ratio, whatever width it is given.
 *
 *   <AspectRatio ratio={16 / 9}>
 *     <img src="/cover.png" alt="Dashboard cover" />
 *   </AspectRatio>
 *
 * shadcn's is Radix's padding-bottom wrapper; this one is a single element
 * with CSS `aspect-ratio` (see `aspect-ratio.css`). ui-sdk has no aspect-ratio
 * or media primitive (its only `aspect` options are on resize handles and
 * ImageCropper's crop box), and there is no behaviour, so it is plain markup.
 */

export type AspectRatioProps = JSX.HTMLAttributes<HTMLDivElement> & {
  /** Width over height, like `16 / 9`. Defaults to 1. */
  ratio?: number;
};

export function AspectRatio(props: AspectRatioProps) {
  const rest = omit(props, "ratio", "style");

  const style = (): JSX.CSSProperties | string => {
    const ratio = String(props.ratio ?? 1);
    const own = props.style;

    return typeof own === "string"
      ? `${own};--aspect-ratio:${ratio}`
      : { ...own, "--aspect-ratio": ratio };
  };

  return <div {...rest} data-slot="aspect-ratio" style={style()} />;
}

/*
 * Aspect Ratio. Neither opencode's console nor @opencode/ui has one: the
 * console's stylesheet has a single Tailwind utility (`.aspect-[2/1]`) and
 * @opencode/ui only sets `aspect-ratio` inside other components (logo,
 * spinner, checkbox), so this is built from scratch.
 *
 * shadcn's AspectRatio is Radix's, which reserves the height with the old
 * padding-bottom hack and an absolutely positioned inner wrapper. Every
 * browser Kitsaas targets supports CSS `aspect-ratio`, so this is one element
 * with the native property. The ratio comes in as `--aspect-ratio` (set by the
 * `ratio` prop, or by a class like `[--aspect-ratio:2]`).
 *
 * `min-height: 0` keeps the box at its ratio when its content is taller
 * (otherwise `aspect-ratio` lets the min-content height win), matching Radix,
 * whose content never resizes the box. Like shadcn's it is unstyled: rounding,
 * borders and fills are left to the caller.
 *
 * Kitsaas addition: a direct <img>, <video>, <iframe>, <canvas>, <svg> or
 * <picture> child fills the box, with `object-fit: cover` on images and
 * video, which is what shadcn's examples do with `h-full w-full object-cover`.
 */

@layer components {
  [data-slot="aspect-ratio"] {
    position: relative;
    width: 100%;
    min-height: 0;
    aspect-ratio: var(--aspect-ratio, 1);
  }

  [data-slot="aspect-ratio"] > :is(img, video, iframe, canvas, svg, picture) {
    display: block;
    width: 100%;
    height: 100%;
  }

  [data-slot="aspect-ratio"] > :is(img, video) {
    object-fit: cover;
  }
}
